/*
 * Service worker for the Louvre guide. The copy in dist/ is generated by
 * tools/build-sw.mjs, which substitutes the version and the precache list.
 * Edit this file, never dist/sw.js.
 *
 * The rule that matters: a cache hit never touches the network. Museum wifi
 * does not fail cleanly, it fails by answering, so anything already downloaded
 * is read from disk and the network is not consulted at all.
 */
const VERSION = '__VERSION__'
const SHELL_CACHE = `louvre-shell-${VERSION}`
/* Not versioned. The images are 16 MB and they do not change between builds;
 * throwing them away because a paragraph was reworded is the one mistake this
 * app cannot recover from inside a gallery. */
const IMAGE_CACHE = 'louvre-images-v1'
const SHELL = __SHELL__
/* Every navigation is answered with this one entry. It is cached under "/",
 * not "/index.html", because Cloudflare redirects /index.html to / and a
 * response that arrived through a redirect is not allowed to answer a
 * navigation. Caching the wrong one of the two fails only when offline. */
const SHELL_HTML = '/'

self.addEventListener('install', (event) => {
  // No skipWaiting. A new worker waits for the visitor to tap update, because
  // swapping the app out from under someone mid-gallery is the opposite of
  // what this is for.
  event.waitUntil(precache())
})

async function precache() {
  const cache = await caches.open(SHELL_CACHE)
  await Promise.all(
    SHELL.map(async (url) => {
      const res = await fetch(url, { cache: 'reload' })
      if (!res.ok) throw new Error(`precache ${url} ${res.status}`)
      // Strip the redirect flag if the asset server redirected us here.
      const clean = res.redirected
        ? new Response(await res.blob(), { status: 200, headers: res.headers })
        : res
      await cache.put(url, clean)
    }),
  )
}

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys()
      await Promise.all(
        names
          .filter((n) => n.startsWith('louvre-shell-') && n !== SHELL_CACHE)
          .map((n) => caches.delete(n)),
      )
      await self.clients.claim()
    })(),
  )
})

self.addEventListener('fetch', (event) => {
  const { request } = event
  if (request.method !== 'GET') return
  if (new URL(request.url).origin !== self.location.origin) return

  // Deep links like /en/item/mona-lisa have no file behind them. Every
  // navigation is answered with the cached shell and the router takes over.
  if (request.mode === 'navigate') {
    event.respondWith(shell())
    return
  }
  event.respondWith(cacheFirst(request))
})

async function shell() {
  const cache = await caches.open(SHELL_CACHE)
  const hit = await cache.match(SHELL_HTML)
  if (hit) return hit
  try {
    return await fetch(SHELL_HTML)
  } catch {
    return offline()
  }
}

async function cacheFirst(request) {
  const hit = await caches.match(request)
  if (hit) return hit
  try {
    return await fetch(request)
  } catch {
    return offline()
  }
}

function offline() {
  return new Response('', { status: 504, statusText: 'Offline and not cached' })
}

self.addEventListener('message', (event) => {
  const data = event.data || {}
  if (data.type === 'SKIP_WAITING') self.skipWaiting()
  if (data.type === 'CACHE_IMAGES') event.waitUntil(cacheImages(data.urls || [], event.source))
  if (data.type === 'IMAGE_STATUS') event.waitUntil(imageStatus(data.urls || [], event.source))
})

/*
 * The explicit download. Sequential on purpose: a phone on museum wifi with 78
 * parallel requests in flight is how this step fails, and progress a visitor
 * can watch is worth more here than finishing two seconds sooner.
 */
async function cacheImages(urls, client) {
  const cache = await caches.open(IMAGE_CACHE)
  let done = 0
  const failed = []
  for (const url of urls) {
    try {
      if (await cache.match(url)) {
        done++
      } else {
        const res = await fetch(url, { cache: 'no-store' })
        if (!res.ok) throw new Error(String(res.status))
        await cache.put(url, res)
        done++
      }
    } catch {
      failed.push(url)
    }
    client?.postMessage({ type: 'IMAGE_PROGRESS', done, total: urls.length, failed: failed.length })
  }
  client?.postMessage({ type: 'IMAGE_DONE', done, total: urls.length, failed })
}

/* Checked on every launch. Knowing which works have no image beats finding out
 * by tapping one in front of the work itself. */
async function imageStatus(urls, client) {
  const cache = await caches.open(IMAGE_CACHE)
  const missing = []
  for (const url of urls) if (!(await cache.match(url))) missing.push(url)
  client?.postMessage({ type: 'IMAGE_STATUS', total: urls.length, missing })
}
